// Labels are a service-local extension of the shared Resource shape.
function labeled(id: string, branch: string, depends_on: string[] = [], key = "Branch"): Resource & { labels: Record<string, string> } {
  return { ...res(id, "instance", null, depends_on), labels: { [key]: branch, Team: "payments" } };
}

test("label keys are case-insensitive for grouping, selectors and branch planning", () => {
  const resources = [
    ...FIXTURE,
    labeled("cdk-a", "feat-a", ["sub-a"], "bRaNcH"),
    labeled("cdk-b", "feat-b", ["net-b"]),
    labeled("different-case", "FEAT-A"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s) => s.id).sort(), ["cdk-a", "i-a", "net-a", "sub-a", "vol-a"]);
  assert.ok(plan.steps.findIndex((s) => s.id === "cdk-a") < plan.steps.findIndex((s) => s.id === "sub-a"));
  assert.equal(byBranch(resources).get("feat-a")?.length, 4);
  assert.match(summarize(resources), /2 untagged resources/);
  assert.ok(matches(resources[6], [["branch", "feat-a"], ["team", "payments"]]));
  assert.ok(!matches(resources[6], [["branch", "FEAT-A"]]));
});

test("legacy tags take precedence over labels", () => {
  const resource = { ...labeled("mixed", "feat-b"), tags: { branch: "feat-a" } };
  assert.equal(byBranch([resource]).get("feat-a")?.length, 1);
  assert.equal(buildPlan([resource], "feat-b").steps.length, 0);
});

test("label-owned resources still respect genuine external dependents", () => {
  const plan = buildPlan([...FIXTURE, labeled("external", "feat-b", ["net-a"])], "feat-a");
  assert.deepEqual(plan.blocked, [{ id: "net-a", dependents: ["external"] }]);
  assert.ok(!plan.steps.some((s) => s.id === "external"));
});

test("a label-owned resource can identify an untagged stack sibling", () => {
  const owner = { ...labeled("owner", "feat-a", ["sibling"]), stack_id: "custom-stack" };
  const sibling = res("sibling", "volume", null, [], "custom-stack");
  const other = res("other", "volume", "feat-b", [], "custom-stack");
  assert.deepEqual(buildPlan([owner, sibling, other], "feat-a").steps.map((s) => s.id), ["owner", "sibling"]);
});
