import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

const cliPath = fileURLToPath(new URL("../src/cli.ts", import.meta.url));

function resource(id: string, extra: Record<string, unknown> = {}) {
  return { id, type: "instance", name: id, tags: {}, stack_id: null,
    depends_on: [] as string[], cost_month_cents: 100, ...extra };
}

async function fixture(external = false) {
  let resources = [
    resource("network", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("boot", { stack_id: "stk-feat-a" }),
    ...Array.from({ length: 18 }, (_, i) => resource(`other-${i}`, { tags: { branch: "feat-b" } })),
    // These only appear on page two, and have no tags or stack ownership.
    resource("cdk-instance", { labels: { bRaNcH: "feat-a" }, depends_on: ["network", "boot"] }),
    resource("cdk-dns", { labels: { BRANCH: "feat-a" }, depends_on: ["cdk-instance"] }),
    resource("other-cdk", { labels: { Branch: "feat-b" } }),
    ...(external ? [resource("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] })] : []),
  ];
  const deleted: string[] = [];
  const cursors: string[] = [];
  let rateLimited = false;
  const server = createServer(async (req, res) => {
    const reply = (status: number, body: unknown) => {
      res.writeHead(status, { "content-type": "application/json" });
      res.end(JSON.stringify(body));
    };
    if (req.headers.authorization !== "Bearer fixture-token") return reply(401, { error: "unauthorized" });
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      // The adapter must use the shared client's retry handling, not raw fetch.
      if (!rateLimited) {
        rateLimited = true;
        res.setHeader("retry-after", "0");
        return reply(429, { error: "rate limited" });
      }
      assert.equal(url.searchParams.get("limit"), "20");
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      const start = cursor === "0" ? 0 : 20;
      return reply(200, { resources: resources.slice(start, start + 20),
        next_cursor: start + 20 < resources.length ? "page/2" : null });
    }
    if (req.method === "DELETE" && url.pathname.startsWith("/v1/resources/")) {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      if (resources.some((r) => r.depends_on.includes(id))) return reply(409, { error: "resource has dependents" });
      if (!resources.some((r) => r.id === id)) return reply(404, { error: "not found" });
      deleted.push(id);
      resources = resources.filter((r) => r.id !== id);
      return reply(200, { deleted: id });
    }
    reply(404, { error: "unknown route" });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  return {
    deleted, cursors,
    remaining: () => resources,
    close: () => new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve())),
    run: (...args: string[]) => new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve, reject) => {
      const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", cliPath, ...args], {
        env: { ...process.env, ENVCTL_API: baseUrl, ENVCTL_TOKEN: "fixture-token" },
      });
      let stdout = "", stderr = "";
      child.stdout.on("data", (data) => { stdout += data; });
      child.stderr.on("data", (data) => { stderr += data; });
      child.on("error", reject);
      child.on("close", (code) => resolve({ code, stdout, stderr }));
    }),
  };
}

test("CLI preserves paginated labels for plan, list, gc, and safe teardown", { timeout: 15000 }, async (t) => {
  const api = await fixture();
  t.after(() => api.close());
  const result = await api.run("plan", "--branch", "feat-a", "--json");
  assert.equal(result.code, 0, result.stderr);
  assert.match(result.stderr, /rate limited/);
  assert.deepEqual(api.cursors, ["0", "page/2"]);
  const plan = JSON.parse(result.stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((s: { id: string }) => s.id).sort(), ["boot", "cdk-dns", "cdk-instance", "network"]);
  const listing = await api.run("list");
  assert.equal(listing.code, 0, listing.stderr);
  assert.match(listing.stdout, /feat-a\s+3\s/);
  assert.match(listing.stdout, /1 untagged resources/); // only the legacy untagged boot volume
  const gc = await api.run("gc", "--untagged");
  assert.equal(gc.code, 0, gc.stderr);
  assert.match(gc.stdout, /^1 untagged resources/);
  const dryRun = await api.run("teardown", "--branch", "feat-a", "--dry-run");
  assert.equal(dryRun.code, 0, dryRun.stderr);
  assert.deepEqual(api.deleted, []);
  const teardown = await api.run("teardown", "--branch", "feat-a");
  assert.equal(teardown.code, 0, teardown.stderr);
  assert.match(teardown.stdout, /complete \(4 resources\)/);
  assert.deepEqual(api.deleted.slice(0, 2), ["cdk-dns", "cdk-instance"]);
  assert.equal(api.remaining().length, 19);
  assert.ok(api.remaining().every((r) => r.id.startsWith("other-")));
  const empty = await api.run("plan", "--branch", "feat-a", "--json");
  assert.equal(empty.code, 0, empty.stderr);
  assert.deepEqual(JSON.parse(empty.stdout).steps, []);
});

test("CLI refuses teardown when a genuinely different branch depends on it", { timeout: 15000 }, async (t) => {
  const api = await fixture(true);
  t.after(() => api.close());
  const result = await api.run("teardown", "--branch", "feat-a");
  assert.equal(result.code, 1);
  assert.match(result.stderr, /refusing to tear down/);
  assert.match(result.stdout, /external.*outside this branch/);
  assert.deepEqual(api.deleted, []);
  assert.equal(api.remaining().length, 24);
});
